function ApplyCharacterSkin(string CharacterName)
{
    DrawScale = Default.DrawScale;
    SetCollisionSize(Default.CollisionRadius, Default.CollisionHeight);

    if (CharacterName ~= "Ron")
    {
        Mesh = SkeletalMesh'HPModels.skronPlayerMesh';
        EnsureVersusPlayerAnimationSet();
    }
    else if (CharacterName ~= "Hermione")
    {
        Mesh = SkeletalMesh'HPModels.skhermionePlayerMesh';
        EnsureVersusPlayerAnimationSet();
    }
    else
    {
        Mesh = SkeletalMesh'HPModels.skharryMesh';
    }

    // Create the cloak channels at the same point where the player mesh is
    // assigned. Pawn Tick is not guaranteed to run during every replicated
    // presentation path, while the channel actors keep themselves in sync.
    if (Mesh == SkeletalMesh'HPModels.skronPlayerMesh'
        || Mesh == SkeletalMesh'HPModels.skhermionePlayerMesh')
    {
        EnsureVersusCloakAnimationChannels();
        UpdateVersusCloakAnimation();
    }

    Log("HPVersusCharacterSkin pawn=" $ string(self)
        $ " character=" $ CharacterName
        $ " mesh=" $ string(Mesh)
        $ " animSet=" $ string(SkelAnim)
        $ " hasJump=" $ string(HasAnim(HarryAnims[0].Jump))
        $ " hasRunback=" $ string(HasAnim(HarryAnims[0].WalkBack)));
}
